<?php require_once "db.php";$id=(int)($_GET["restaurant_id"]??0);$s=$conn->prepare("SELECT name FROM restaurants WHERE id=?");$s->bind_param("i",$id);$s->execute();$rest=$s->get_result()->fetch_assoc();$s=$conn->prepare("SELECT * FROM menu_items WHERE restaurant_id=?");$s->bind_param("i",$id);$s->execute();$items=$s->get_result(); ?>
